sp_widget.css:
 .info-title {
    background-color: #e0e0e0;
    color: #000;
    padding: 8px 12px;
    border-radius: 4px 4px 0 0;
    margin: 16px 0 0 0;
    font-size: 18px;
    font-family: 'Roboto Flex', sans-serif;
 }


h4, h3, h2, div, p{
	  font-family: 'Roboto Flex', sans-serif;
}

 /* Caixa principal */
 .info-box {
    font-family: 'Roboto Flex', sans-serif;
    border: 1px solid #ccc;
    padding: 10px 14px;
    background-color: #f9f9f9;
    border-radius: 0 0 4px 4px;
    margin: 0;
    font-size: 13px;
    color: #333;
    line-height: 1.4;
    max-width: 100%;
    box-sizing: border-box;
 }

 /* Layout das colunas internas */
 .info-rows {
    display: flex;
    flex-wrap: wrap;
    gap: 40px;
 }

 .info-column {
    flex: 1 1 300px;
    box-sizing: border-box;
 }

 /* Títulos internos */
 .info-column h4 {
    margin-bottom: 8px;
    color: #000;
    font-size: 15px;
    border-bottom: 1px solid #ccc;
    padding-bottom: 4px;
    font-weight: 600;
 }

 /* Itens */
 .info-column p {
    margin: 4px 0;
 }

 .sub-info {
    color: #0066cc;
    font-weight: 500;
 }

 /* --- Responsividade --- */
 @media (max-width: 767px) {
   .info-rows {
      flex-direction: column;
   }
   .info-title {
      font-size: 1rem;
      padding: 6px 10px;
      margin-top: 1rem;
   }
   .info-box {
      font-size: 0.85rem;
      padding: 8px 10px;
      line-height: 1.3;
   }
   .info-column h4 {
      font-size: 0.95rem;
   }
 }
